parameters.jsCode:
const body = $input.item.json;
const messages = body.messages || [];
const transcript = messages
  .map(m => `${m.role || 'user'}: ${m.text || m.content || ''}`)
  .join('\n');

return {
  household_hash: body.household_hash || '',
  call_id: body.call_id || '',
  phone_number: body.customer_number || body.phone_number || '',
  transcript: transcript,
  metadata: body.metadata || {}
};

const STATE_MAP = {
  'karnataka': 'KA', 'tamil nadu': 'TN', 'maharashtra': 'MH',
  'andhra pradesh': 'AP', 'telangana': 'TS', 'kerala': 'KL',
  'uttar pradesh': 'UP', 'rajasthan': 'RJ', 'west bengal': 'WB',
  'madhya pradesh': 'MP', 'gujarat': 'GJ', 'odisha': 'OD',
  'punjab': 'PB', 'haryana': 'HR', 'bihar': 'BR', 'assam': 'AS',
  'jharkhand': 'JH', 'chhattisgarh': 'CG', 'uttarakhand': 'UK',
  'himachal pradesh': 'HP', 'goa': 'GA', 'manipur': 'MN',
  'meghalaya': 'ML', 'mizoram': 'MZ', 'nagaland': 'NL',
  'sikkim': 'SK', 'tripura': 'TR', 'arunachal pradesh': 'AR'
};

const groqResp = $input.item.json;
const content = groqResp?.choices?.[0]?.message?.content || '{}';

let extracted = {};
try { extracted = JSON.parse(content); } catch(e) {}

const stateName = (extracted.state || '').toLowerCase().trim();
const state_code = STATE_MAP[stateName] || 'KA';

const prepData = $node['Prepare Transcript'].json;

return {
  ...extracted,
  state_code: state_code,
  household_hash: prepData.household_hash,
  call_id: prepData.call_id,
  phone_number: prepData.phone_number
};

const rulesResult = $input.item.json;
const schemes = rulesResult.eligible_schemes || rulesResult.schemes || rulesResult.results || [];
const best = Array.isArray(schemes) && schemes.length > 0 ? schemes[0] : null;

const parseData = $node['Parse Entities + Map State'].json;

return {
  ...parseData,
  best_scheme_id: best?.scheme_id || best?.id || 'ka-old-age-pension',
  best_scheme_name: best?.scheme_name || best?.name || 'Government Pension Scheme',
  all_schemes: schemes
};

const submissionData = $input.item.json;
const schemeData = $node['Select Best Scheme'].json;

const scheme_id = schemeData.best_scheme_id || 'ka-old-age-pension';

const SCHEME_TEMPLATE = {
  'ka-old-age-pension': 'pension1.pdf',
  'ka-widow-pension': 'pension1.pdf',
  'widow_pension_001': 'pension1.pdf',
  'old_age_pension_001': 'pension1.pdf',
  'ka-disability-pension': 'disabledgovt.pdf',
  'disability_pension_001': 'disabledgovt.pdf',
  'pmjay': 'Application_for_assiatance.pdf',
  'girl_scholarship_001': 'pratibhaschem.pdf',
  'ration_apl_001': 'formsandregister.pdf'
};
const template = SCHEME_TEMPLATE[scheme_id] || 'pension1.pdf';

const FIELD_MAP = {
  'pension1.pdf': [
    {field_id:'name', x:400, y:712, page:1, fontSize:10},
    {field_id:'age', x:400, y:648, page:1, fontSize:10},
    {field_id:'date_of_birth', x:460, y:648, page:1, fontSize:10},
    {field_id:'gender', x:400, y:627, page:1, fontSize:10},
    {field_id:'address', x:400, y:478, page:1, fontSize:9},
    {field_id:'phone', x:400, y:440, page:1, fontSize:10},
    {field_id:'aadhaar_number', x:400, y:415, page:1, fontSize:10},
    {field_id:'annual_income', x:400, y:352, page:1, fontSize:10}
  ],
  'disabledgovt.pdf': [
    {field_id:'name', x:380, y:680, page:1, fontSize:10},
    {field_id:'age', x:380, y:640, page:1, fontSize:10},
    {field_id:'address', x:380, y:580, page:1, fontSize:9},
    {field_id:'phone', x:380, y:540, page:1, fontSize:10},
    {field_id:'aadhaar_number', x:380, y:500, page:1, fontSize:10}
  ]
};

const field_values = {
  name: schemeData.name || '',
  age: String(schemeData.age || ''),
  date_of_birth: schemeData.dob || '',
  gender: schemeData.gender || '',
  address: schemeData.address || '',
  phone: schemeData.phone || schemeData.phone_number || '',
  aadhaar_number: schemeData.aadhaar_number || '',
  annual_income: String(schemeData.monthly_income || '')
};

return {
  template_path: `/app/templates/${template}`,
  form_fields: FIELD_MAP[template] || FIELD_MAP['pension1.pdf'],
  field_values: field_values,
  household_hash: schemeData.household_hash,
  scheme_id: scheme_id,
  submission_id: submissionData.submission_id || ''
};

const fillResult = $input.item.json;
const buildData = $node['Build PDF Fill Payload'].json;

const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const filename = `${buildData.household_hash}/filled_forms/${buildData.scheme_id}_${ts}.pdf`;

return {
  bucket: 'filled-forms',
  filename: filename,
  document_data: fillResult.filled_document_base64 || '',
  fields_empty: fillResult.fields_empty || [],
  fill_confidence: fillResult.fill_confidence || 0,
  household_hash: buildData.household_hash,
  scheme_id: buildData.scheme_id,
  submission_id: buildData.submission_id
};

const uploadResult = $input.item.json;
const buildData = $node['Build Upload Payload'].json;

const storage_path = uploadResult.storage_path || buildData.filename;
const filled_pdf_uri = `minio://${storage_path}`;

return {
  household_hash: buildData.household_hash,
  scheme_id: buildData.scheme_id,
  filled_pdf_uri: filled_pdf_uri,
  fields_empty: buildData.fields_empty || [],
  fill_confidence: buildData.fill_confidence || 0,
  submission_id: buildData.submission_id
};

const updateResult = $input.item.json;
const buildData = $node['Build Update Payload'].json;
const schemeData = $node['Select Best Scheme'].json;

return {
  household_hash: buildData.household_hash,
  status: updateResult.submission_status || 'pdf_ready',
  filled_pdf_uri: buildData.filled_pdf_uri,
  fields_empty: buildData.fields_empty || [],
  best_scheme: {
    scheme_id: schemeData.best_scheme_id,
    scheme_name: schemeData.best_scheme_name
  }
};
